from __future__ import annotations

from dataclasses import dataclass, field
from types import MappingProxyType
from typing import Any, Mapping


def _normalize_members(values: set[str]) -> tuple[str, ...]:
    return tuple(sorted({value.strip() for value in values if value and value.strip()}))


def _safe_mapping_copy(claims: Mapping[str, Any] | None) -> Mapping[str, Any]:
    return MappingProxyType(dict(claims or {}))


@dataclass(frozen=True)
class AuthenticatedPrincipal:
    subject: str
    issuer: str | None = None
    audiences: tuple[str, ...] = ()
    display_name: str | None = None
    email: str | None = None
    groups: tuple[str, ...] = ()
    roles: tuple[str, ...] = ()
    scopes: tuple[str, ...] = ()
    claims: Mapping[str, Any] = field(
        default_factory=lambda: MappingProxyType({}),
        repr=False,
        compare=False,
    )

    def __post_init__(self) -> None:
        object.__setattr__(self, "subject", self.subject.strip())
        object.__setattr__(
            self,
            "audiences",
            _normalize_members(set(self.audiences)),
        )
        object.__setattr__(
            self,
            "groups",
            _normalize_members(set(self.groups)),
        )
        object.__setattr__(
            self,
            "roles",
            _normalize_members({role.lower() for role in self.roles}),
        )
        object.__setattr__(
            self,
            "scopes",
            _normalize_members({scope.lower() for scope in self.scopes}),
        )
        object.__setattr__(self, "claims", _safe_mapping_copy(self.claims))

    def has_role(self, role: str) -> bool:
        wanted = role.strip().lower()
        return wanted in self.roles

    def has_any_role(self, *roles: str) -> bool:
        wanted = {role.strip().lower() for role in roles if role and role.strip()}
        return bool(wanted.intersection(self.roles))

    def has_all_roles(self, *roles: str) -> bool:
        wanted = {role.strip().lower() for role in roles if role and role.strip()}
        return wanted.issubset(set(self.roles))

    def has_group(self, group: str) -> bool:
        wanted = group.strip().casefold()
        return any(existing.casefold() == wanted for existing in self.groups)

    def has_scope(self, scope: str) -> bool:
        wanted = scope.strip().lower()
        return wanted in self.scopes

    def to_safe_log_context(self) -> dict[str, Any]:
        return {
            "subject": self.subject,
            "issuer": self.issuer,
            "audience_count": len(self.audiences),
            "group_count": len(self.groups),
            "roles": list(self.roles),
            "scope_count": len(self.scopes),
        }


@dataclass(frozen=True)
class AuthorizationDecision:
    allowed: bool
    required_roles: tuple[str, ...] = ()
    principal_roles: tuple[str, ...] = ()
    missing_roles: tuple[str, ...] = ()
    reason: str | None = None

    @classmethod
    def allow(cls, principal: AuthenticatedPrincipal, required_roles: tuple[str, ...] = ()) -> "AuthorizationDecision":
        return cls(
            allowed=True,
            required_roles=_normalize_members({role.lower() for role in required_roles}),
            principal_roles=principal.roles,
            missing_roles=(),
            reason=None,
        )

    @classmethod
    def deny(
        cls,
        principal: AuthenticatedPrincipal,
        *,
        required_roles: tuple[str, ...],
        missing_roles: tuple[str, ...],
        reason: str,
    ) -> "AuthorizationDecision":
        return cls(
            allowed=False,
            required_roles=_normalize_members({role.lower() for role in required_roles}),
            principal_roles=principal.roles,
            missing_roles=_normalize_members({role.lower() for role in missing_roles}),
            reason=reason,
        )

    def to_log_context(self) -> dict[str, Any]:
        return {
            "allowed": self.allowed,
            "required_roles": list(self.required_roles),
            "principal_roles": list(self.principal_roles),
            "missing_roles": list(self.missing_roles),
            "reason": self.reason,
        }
