from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from typing import Mapping


def _parse_bool(value: str | None, default: bool) -> bool:
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _parse_csv(value: str | None, default: tuple[str, ...] = ()) -> tuple[str, ...]:
    if value is None:
        return default
    values = [item.strip() for item in value.split(",")]
    return tuple(item for item in values if item)


def _parse_role_map_json(value: str | None) -> dict[str, tuple[str, ...]]:
    if not value:
        return {}

    parsed = json.loads(value)
    if not isinstance(parsed, dict):
        raise ValueError("AUTHZ_ROLE_MAP_JSON must be a JSON object of role -> list[str].")

    result: dict[str, tuple[str, ...]] = {}
    for role, groups in parsed.items():
        if not isinstance(role, str):
            raise ValueError("AUTHZ_ROLE_MAP_JSON keys must be strings.")
        if not isinstance(groups, list) or not all(isinstance(group, str) for group in groups):
            raise ValueError("AUTHZ_ROLE_MAP_JSON values must be lists of strings.")
        normalized_role = role.strip().lower()
        result[normalized_role] = tuple(sorted({group.strip() for group in groups if group.strip()}))
    return result


@dataclass(frozen=True)
class AuthzSettings:
    enabled: bool = True
    issuer: str | None = None
    audiences: tuple[str, ...] = ()
    principal_claim_candidates: tuple[str, ...] = ("sub", "preferred_username", "email", "upn")
    display_name_claim_candidates: tuple[str, ...] = ("name", "preferred_username", "email")
    email_claim_candidates: tuple[str, ...] = ("email", "upn")
    group_claim_paths: tuple[str, ...] = ("groups",)
    role_claim_paths: tuple[str, ...] = ("roles", "realm_access.roles", "resource_access.account.roles")
    scope_claim_candidates: tuple[str, ...] = ("scope", "scp")
    default_roles: tuple[str, ...] = ()
    role_bindings: Mapping[str, tuple[str, ...]] = field(default_factory=dict)
    safe_log_claims: tuple[str, ...] = ("sub", "iss", "aud", "scope", "scp", "groups", "roles", "email")

    @classmethod
    def from_env(cls, prefix: str = "AUTHZ_") -> "AuthzSettings":
        issuer = os.getenv(f"{prefix}ISSUER") or None

        role_bindings = {
            "admin": _parse_csv(os.getenv(f"{prefix}ADMIN_GROUPS")),
            "validator": _parse_csv(os.getenv(f"{prefix}VALIDATOR_GROUPS")),
            "operator": _parse_csv(os.getenv(f"{prefix}OPERATOR_GROUPS")),
            "reader": _parse_csv(os.getenv(f"{prefix}READER_GROUPS")),
            "service": _parse_csv(os.getenv(f"{prefix}SERVICE_GROUPS")),
        }

        role_bindings = {
            role: groups
            for role, groups in role_bindings.items()
            if groups
        }

        role_bindings.update(_parse_role_map_json(os.getenv(f"{prefix}ROLE_MAP_JSON")))

        return cls(
            enabled=_parse_bool(os.getenv(f"{prefix}ENABLED"), True),
            issuer=issuer,
            audiences=_parse_csv(os.getenv(f"{prefix}AUDIENCES")),
            principal_claim_candidates=_parse_csv(
                os.getenv(f"{prefix}PRINCIPAL_CLAIMS"),
                ("sub", "preferred_username", "email", "upn"),
            ),
            display_name_claim_candidates=_parse_csv(
                os.getenv(f"{prefix}DISPLAY_NAME_CLAIMS"),
                ("name", "preferred_username", "email"),
            ),
            email_claim_candidates=_parse_csv(
                os.getenv(f"{prefix}EMAIL_CLAIMS"),
                ("email", "upn"),
            ),
            group_claim_paths=_parse_csv(
                os.getenv(f"{prefix}GROUP_CLAIM_PATHS"),
                ("groups",),
            ),
            role_claim_paths=_parse_csv(
                os.getenv(f"{prefix}ROLE_CLAIM_PATHS"),
                ("roles", "realm_access.roles", "resource_access.account.roles"),
            ),
            scope_claim_candidates=_parse_csv(
                os.getenv(f"{prefix}SCOPE_CLAIMS"),
                ("scope", "scp"),
            ),
            default_roles=tuple(
                sorted(
                    {
                        role.strip().lower()
                        for role in _parse_csv(os.getenv(f"{prefix}DEFAULT_ROLES"))
                        if role.strip()
                    }
                )
            ),
            role_bindings=role_bindings,
            safe_log_claims=_parse_csv(
                os.getenv(f"{prefix}SAFE_LOG_CLAIMS"),
                ("sub", "iss", "aud", "scope", "scp", "groups", "roles", "email"),
            ),
        )

    def normalized_role_bindings(self) -> dict[str, set[str]]:
        return {
            role.strip().lower(): {group.casefold() for group in groups}
            for role, groups in self.role_bindings.items()
            if role.strip()
        }

    def requires_issuer_validation(self) -> bool:
        return bool(self.issuer)

    def requires_audience_validation(self) -> bool:
        return bool(self.audiences)

    def to_safe_summary(self) -> dict[str, object]:
        return {
            "enabled": self.enabled,
            "issuer_configured": bool(self.issuer),
            "audience_count": len(self.audiences),
            "principal_claim_candidates": list(self.principal_claim_candidates),
            "group_claim_paths": list(self.group_claim_paths),
            "role_claim_paths": list(self.role_claim_paths),
            "configured_roles": sorted(self.role_bindings.keys()),
        }
