from __future__ import annotations

from typing import Any, Iterable, Mapping

from .models import AuthenticatedPrincipal
from .settings import AuthzSettings


class ClaimsValidationError(ValueError):
    pass


def _as_mapping(value: Any) -> Mapping[str, Any] | None:
    return value if isinstance(value, Mapping) else None


def _deep_get(mapping: Mapping[str, Any], path: str) -> Any:
    current: Any = mapping
    for part in path.split("."):
        nested = _as_mapping(current)
        if nested is None or part not in nested:
            return None
        current = nested[part]
    return current


def _coerce_string_values(value: Any, *, split_spaces: bool = False) -> tuple[str, ...]:
    if value is None:
        return ()

    if isinstance(value, str):
        if split_spaces:
            parts = [part.strip() for part in value.split()]
        else:
            parts = [part.strip() for part in value.split(",")]
        return tuple(part for part in parts if part)

    if isinstance(value, (list, tuple, set, frozenset)):
        result: list[str] = []
        for item in value:
            if isinstance(item, str):
                stripped = item.strip()
                if stripped:
                    result.append(stripped)
        return tuple(result)

    return (str(value).strip(),) if str(value).strip() else ()


def _collect_values(
    claims: Mapping[str, Any],
    paths: Iterable[str],
    *,
    split_spaces: bool = False,
) -> tuple[str, ...]:
    collected: list[str] = []
    for path in paths:
        value = _deep_get(claims, path)
        collected.extend(_coerce_string_values(value, split_spaces=split_spaces))
    return tuple(sorted({item for item in collected if item}))


def _first_non_empty(claims: Mapping[str, Any], candidates: Iterable[str]) -> str | None:
    for candidate in candidates:
        value = _deep_get(claims, candidate)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def _normalize_roles(values: Iterable[str]) -> tuple[str, ...]:
    return tuple(sorted({value.strip().lower() for value in values if value and value.strip()}))


def validate_claims(claims: Mapping[str, Any], settings: AuthzSettings) -> None:
    if not settings.enabled:
        return

    if settings.requires_issuer_validation():
        issuer = _deep_get(claims, "iss")
        if issuer != settings.issuer:
            raise ClaimsValidationError("Token issuer did not match configured issuer.")

    if settings.requires_audience_validation():
        audiences = set(_collect_values(claims, ("aud",)))
        if not audiences.intersection(settings.audiences):
            raise ClaimsValidationError("Token audience did not match any configured audience.")


def derive_roles(claims: Mapping[str, Any], groups: tuple[str, ...], settings: AuthzSettings) -> tuple[str, ...]:
    explicit_roles = _normalize_roles(_collect_values(claims, settings.role_claim_paths))
    derived_roles = set(explicit_roles)
    derived_roles.update(settings.default_roles)

    if groups:
        normalized_groups = {group.casefold() for group in groups}
        for role, bound_groups in settings.normalized_role_bindings().items():
            if normalized_groups.intersection(bound_groups):
                derived_roles.add(role)

    return tuple(sorted(derived_roles))


def build_principal(claims: Mapping[str, Any], settings: AuthzSettings | None = None) -> AuthenticatedPrincipal:
    if not isinstance(claims, Mapping) or not claims:
        raise ClaimsValidationError("Claims payload must be a non-empty mapping.")

    resolved_settings = settings or AuthzSettings()
    validate_claims(claims, resolved_settings)

    subject = _first_non_empty(claims, resolved_settings.principal_claim_candidates)
    if not subject:
        raise ClaimsValidationError("Token claims did not include a usable principal identifier.")

    groups = _collect_values(claims, resolved_settings.group_claim_paths)
    roles = derive_roles(claims, groups, resolved_settings)
    scopes = _normalize_roles(_collect_values(claims, resolved_settings.scope_claim_candidates, split_spaces=True))

    audiences = _collect_values(claims, ("aud",))
    return AuthenticatedPrincipal(
        subject=subject,
        issuer=_first_non_empty(claims, ("iss",)),
        audiences=audiences,
        display_name=_first_non_empty(claims, resolved_settings.display_name_claim_candidates),
        email=_first_non_empty(claims, resolved_settings.email_claim_candidates),
        groups=groups,
        roles=roles,
        scopes=scopes,
        claims=claims,
    )
