from __future__ import annotations

from typing import Any, Iterable, Mapping

from .claims import ClaimsValidationError, build_principal
from .models import AuthenticatedPrincipal, AuthorizationDecision
from .settings import AuthzSettings

try:
    from fastapi import HTTPException, status
except Exception:  # pragma: no cover - compatibility fallback for thin local environments
    class HTTPException(Exception):
        def __init__(self, status_code: int, detail: Any) -> None:
            super().__init__(detail)
            self.status_code = status_code
            self.detail = detail

    class _Status:
        HTTP_401_UNAUTHORIZED = 401
        HTTP_403_FORBIDDEN = 403

    status = _Status()


def parse_authorization_header(authorization: str | None) -> str:
    if not authorization:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Missing Authorization header.",
        )

    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or not token.strip():
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authorization header must contain a Bearer token.",
        )
    return token.strip()


def resolve_principal_from_claims(
    claims: Mapping[str, Any],
    settings: AuthzSettings | None = None,
) -> AuthenticatedPrincipal:
    try:
        return build_principal(claims, settings=settings)
    except ClaimsValidationError as exc:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail=str(exc),
        ) from exc


def authorize_roles(
    principal: AuthenticatedPrincipal,
    required_roles: Iterable[str],
    *,
    require_all: bool = False,
) -> AuthorizationDecision:
    normalized = tuple(
        sorted({role.strip().lower() for role in required_roles if role and role.strip()})
    )
    if not normalized:
        return AuthorizationDecision.allow(principal)

    principal_roles = set(principal.roles)
    if require_all:
        missing_roles = tuple(role for role in normalized if role not in principal_roles)
        if not missing_roles:
            return AuthorizationDecision.allow(principal, normalized)
        return AuthorizationDecision.deny(
            principal,
            required_roles=normalized,
            missing_roles=missing_roles,
            reason="principal_missing_required_roles",
        )

    if principal_roles.intersection(normalized):
        return AuthorizationDecision.allow(principal, normalized)

    return AuthorizationDecision.deny(
        principal,
        required_roles=normalized,
        missing_roles=normalized,
        reason="principal_missing_any_required_role",
    )


def require_roles(
    principal: AuthenticatedPrincipal,
    *required_roles: str,
    require_all: bool = False,
) -> AuthenticatedPrincipal:
    decision = authorize_roles(
        principal,
        required_roles=required_roles,
        require_all=require_all,
    )
    if decision.allowed:
        return principal

    raise HTTPException(
        status_code=status.HTTP_403_FORBIDDEN,
        detail={
            "message": "Principal is not authorized for the requested operation.",
            "missing_roles": list(decision.missing_roles),
            "required_roles": list(decision.required_roles),
        },
    )


def role_guard(*required_roles: str, require_all: bool = False):
    def guard(principal: AuthenticatedPrincipal) -> AuthenticatedPrincipal:
        return require_roles(principal, *required_roles, require_all=require_all)

    return guard
