from __future__ import annotations

from typing import Any, Mapping

from .models import AuthenticatedPrincipal, AuthorizationDecision


def _mask_email(value: str | None) -> str | None:
    if not value or "@" not in value:
        return value
    local, domain = value.split("@", 1)
    if not local:
        return f"***@{domain}"
    return f"{local[:1]}***@{domain}"


def _safe_list(values: list[str], *, limit: int = 10) -> list[str]:
    return values[:limit]


def redact_claims_for_log(
    claims: Mapping[str, Any],
    *,
    allowed_keys: tuple[str, ...] = ("sub", "iss", "aud", "scope", "scp", "groups", "roles", "email"),
) -> dict[str, Any]:
    redacted: dict[str, Any] = {}
    for key in allowed_keys:
        if key not in claims:
            continue

        value = claims[key]
        if key == "email" and isinstance(value, str):
            redacted[key] = _mask_email(value)
        elif isinstance(value, str):
            redacted[key] = value
        elif isinstance(value, (list, tuple, set, frozenset)):
            redacted[key] = _safe_list([str(item) for item in value])
            redacted[f"{key}_count"] = len(value)
        else:
            redacted[key] = str(value)
    return redacted


def principal_log_context(principal: AuthenticatedPrincipal) -> dict[str, Any]:
    context = principal.to_safe_log_context()
    if principal.email:
        context["email"] = _mask_email(principal.email)
    if principal.display_name:
        context["display_name_present"] = True
    return context


def authorization_log_event(
    *,
    action: str,
    resource: str,
    decision: AuthorizationDecision,
    principal: AuthenticatedPrincipal | None = None,
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "event": "authorization_check",
        "action": action,
        "resource": resource,
        "decision": decision.to_log_context(),
    }
    if principal is not None:
        payload["principal"] = principal_log_context(principal)
    if extra:
        payload["extra"] = dict(extra)
    return payload


def emit_authorization_log(
    logger: Any,
    *,
    action: str,
    resource: str,
    decision: AuthorizationDecision,
    principal: AuthenticatedPrincipal | None = None,
    extra: Mapping[str, Any] | None = None,
) -> None:
    event = authorization_log_event(
        action=action,
        resource=resource,
        decision=decision,
        principal=principal,
        extra=extra,
    )
    logger.info("authorization_check", extra=event)
