from backend.shared.authz.dependencies import HTTPException, authorize_roles  # noqa: E402


def test_settings_from_env_parses_role_bindings_and_claim_paths(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setenv("AUTHZ_ISSUER", "https://issuer.example")
    monkeypatch.setenv("AUTHZ_AUDIENCES", "docufu-api,docufu-ui")
    monkeypatch.setenv("AUTHZ_GROUP_CLAIM_PATHS", "groups,realm_access.roles")
    monkeypatch.setenv("AUTHZ_ADMIN_GROUPS", "DocuFu-Admins,Platform-Admins")
    monkeypatch.setenv("AUTHZ_DEFAULT_ROLES", "reader")
    monkeypatch.setenv("AUTHZ_ROLE_MAP_JSON", '{"validator": ["DocuFu-Validators"]}')

    settings = AuthzSettings.from_env()

    assert settings.issuer == "https://issuer.example"
    assert settings.audiences == ("docufu-api", "docufu-ui")
    assert settings.group_claim_paths == ("groups", "realm_access.roles")
    assert settings.default_roles == ("reader",)
    assert settings.role_bindings["admin"] == ("DocuFu-Admins", "Platform-Admins")
    assert settings.role_bindings["validator"] == ("DocuFu-Validators",)


def test_build_principal_extracts_nested_groups_roles_and_scopes() -> None:
    settings = AuthzSettings(
        issuer="https://issuer.example",
        audiences=("docufu-api",),
        group_claim_paths=("groups", "realm_access.roles"),
        role_claim_paths=("roles", "resource_access.account.roles"),
        role_bindings={
            "admin": ("DocuFu-Admins",),
            "validator": ("DocuFu-Validators",),
        },
        default_roles=("reader",),
    )

    claims = {
        "sub": "user-123",
        "iss": "https://issuer.example",
        "aud": ["docufu-api", "other-client"],
        "name": "Jane Operator",
        "email": "jane.operator@example.com",
        "groups": ["DocuFu-Admins", "Team-A"],
        "realm_access": {"roles": ["DocuFu-Validators"]},
        "resource_access": {"account": {"roles": ["operator"]}},
        "scope": "documents.read documents.write",
    }

    principal = build_principal(claims, settings)

    assert principal.subject == "user-123"
    assert principal.display_name == "Jane Operator"
    assert principal.email == "jane.operator@example.com"
    assert principal.has_group("DocuFu-Admins")
    assert principal.roles == ("admin", "operator", "reader", "validator")
    assert principal.scopes == ("documents.read", "documents.write")


def test_build_principal_rejects_missing_subject() -> None:
    claims = {
